{% capture quantity -%}{{ position.Quantity }}{% if position.Unit != empty and position.Unit != null %} {{ Position.Unit }}{% else %}x{% endif %} {{ position.Name }}{% endcapture -%}
{% capture preis -%}{% if UseNetPrice %}{{ position.TotalNetPrice | Nummer : 'C', Report.CultureInfo }}{% else %}{{ position.TotalGrossPrice | Nummer : 'C', Report.CultureInfo }}{% endif %}{% endcapture -%}
  {{ quantity | Truncate: 61 | Align: -61 }}{{ Tabulator }}{{ preis | Truncate: 15 | Align: 15 }}
{% if IncludeSKU == true -%}
{% capture artnr %}Artikelnummer: {{ position.SKU }}{% endcapture -%}
    {{ artnr | Truncate: 59 }}
{% endif -%}
{% if IncludePricePerUnit == true -%}
{% capture ez %}Einzelpreis: {% if UseNetPrice %}{{ position.NetPricePerUnit | Nummer : 'C', Report.CultureInfo }}{% else %}{{ position.GrossPricePerUnit | Nummer : 'C', Report.CultureInfo }}{% endif -%}{% endcapture -%}
    {{ ez | Truncate: 59 }}
{% endif -%}
{% for serialNumberItem in position.SalesQuotationPositionDeliveryDetails -%}
{% capture child -%}Seriennummer: {{ serialNumberItem.SerialNumber }}{% endcapture -%}
