    {{ child | Truncate: 59 }}\
{% endif -%}
{% endfor -%}
{% for configuration in position.SalesQuotationPositionConfiguration -%}
{% capture child %}{{ configuration.Name }}: {{ configuration.ValueText }}{% endcapture -%}
     {{ child | Truncate: 59 }}
{% endfor -%}
{% endif -%}
{% endfor -%}
{% capture desc %}Verpackung und Versand{% if shippingMethod != null %} ({{ shippingMethod }}){% endif %}:{% endcapture -%}
{% capture price %}{% if shippingPrice != empty %}{{ shippingPrice | Nummer : 'C', Report.CultureInfo }}{% else %}{{ 0 | Nummer: 'C', Report.CultureInfo }}{% endif %}{%endcapture -%}
