{% capture price %}{{ salesQuotationTotals.NetPriceTotal | Nummer : 'C', Report.CultureInfo }}{% endcapture -%}
  {{ desc | Truncate: 61 | Align: 61 }}{{ Tabulator }}{{ price | Truncate: 15 | Align: 15 }}
{% endif -%}
{% endfor -%}
{% for salesQuotationTotals in Report.TotalsSalesQuotation -%}
{% if salesQuotationTotals.GrossPriceTotal > 0 or Report.TotalsSalesQuotation.Size == 1 -%}
